const mk = 'Acme: 20% off boxes today. Reply STOP to opt out.';
const m = { kind: 'marketing', text: mk };
const t = { kind: 'transactional', text: 'Acme: your box shipped.' };
const d = (s) => new Date(s);
let fail = 0;
